<?php
namespace App\Models\Documents;
use Illuminate\Database\Eloquent\Model;
class PostedReceipt extends Model { protected $table='posted_receipts'; protected $guarded=[]; protected $casts=['document_date'=>'date','posted_at'=>'datetime','subtotal'=>'decimal:4','discount_total'=>'decimal:4','tax_total'=>'decimal:4','grand_total'=>'decimal:4']; public function lines(){return $this->hasMany(PostedReceiptLine::class,'posted_receipt_id');} public function vendor(){return $this->belongsTo(\App\Models\Vendor::class,'vendor_id');} public function location(){return $this->belongsTo(\App\Models\Location::class,'location_id');} public function bin(){return $this->belongsTo(\App\Models\LocationBin::class,'bin_id');} public function source(){return $this->belongsTo(Receipt::class,'source_receipt_id');} public function glBatch(){return $this->belongsTo(\App\Models\GlBatch::class);} public function undo(){return $this->hasOne(PostedDocumentUndo::class,'posted_id')->where('posted_type','PostedReceipt');} public function effectiveStatus(): string { return $this->undo()->exists()?'UNDO':'POSTED'; } }
